// Typed access to the JSON the export script writes (scripts/export.py), plus the small
// helpers the pages share. The JSON files are generated by the export, which every build runs
// first (`npm run export` runs it alone); they are committed too, so the parent site could read
// tree.json from the repository before the headline file existed (2026-10-17: it now reads
// data/headline.json).
import treeJson from '../data/tree.json';
import changelogJson from '../data/changelog.json';
import claimsJson from '../data/claims.json';
import bandwidthJson from '../data/bandwidth.json';

export const REPO = 'https://github.com/jfredson/upgrade-tree';

export type StageKey = 'idea-only' | 'shown-in-animals' | 'first-human' | 'in-clinical-use' | 'in-wide-use';

export type Stage = { key: StageKey; label: string; meaning: string; rank: number };

export type Ref = { id: string; name: string; path: string; stage: StageKey; stage_label: string };

export type Branch = {
  key: string;
  order: number;
  name: string;
  tagline: string;
  meaning: string;
  figure_region: string;
  path: string;
  count: number;
  counts_by_stage: Record<StageKey, number>;
  furthest_rank: number | null;
  furthest_stage: StageKey | null;
  furthest_label: string | null;
  first_human_or_beyond: number;
  upgrades: Ref[];
};

export type Rung = {
  key: StageKey;
  label: string;
  reached: boolean;
  current: boolean;
  reached_on: string | null;
  record: string | null;
};

export type Revision = { date: string | null; field: string | null; old: unknown; new: unknown; why: string | null };

export type Upgrade = {
  id: string;
  name: string;
  branch: string;
  branch_name: string;
  path: string;
  description: string;
  resolution: string;
  source: string;
  horizon: 'leaf' | 'mid' | 'root' | 'top';
  horizon_label: string;
  status: 'tracked' | 'withdrawn' | 'superseded';
  superseded_by: string | null;
  depends_on: string[];
  depends_on_refs: Ref[];
  needed_by: Ref[];
  stage: StageKey;
  stage_rank: number;
  stage_label: string;
  stage_reached_on: string | null;
  stage_record: string | null;
  ladder: Rung[];
  long_shot: boolean;
  mechanism: string | null;
  breaking_point: string | null;
  revisions: Revision[];
  verify: string[];
  /** Extra search terms for the weekly reading; a search aid only. */
  watch: string[];
  /** The id of the matching leaf on Outrunning Ageing, and its page there, for the five shared lifespan entries (added 2026-10-17). */
  sibling: string | null;
  sibling_url: string | null;
  notes: string | null;
  example: boolean;
};

export type Tree = {
  exported_on: string;
  commit: string | null;
  /** The sibling site the five shared lifespan entries link across to (scripts/export.py, SIBLING_SITE). */
  sibling_site: { name: string; url: string };
  headline_stage: StageKey;
  stages: Stage[];
  horizons: Record<string, string>;
  branches: Branch[];
  upgrades: Upgrade[];
  counts: {
    upgrades: number;
    first_human_or_beyond: number;
    by_stage: Record<StageKey, number>;
    long_shots: number;
    examples: number;
    branches_with_upgrades: number;
    to_verify: number;
    siblings: number;
  };
  /** The latest weekly reading, or null before the first one (scripts/export.py, export_readings). */
  last_checked: {
    date: string;
    scope: 'weekly' | 'monthly';
    by: 'hand' | 'scheduled';
    test: boolean;
    upgrades_read: number;
    moved: number;
    flagged: number;
    noted: number;
    flagged_waiting: number;
    movers: { id: string; name: string; path: string; moved_to_label: string | null }[];
  } | null;
};

export type Changelog = { source: string; intro: string; days: { date: string; items: string[] }[] };

// The claims: what people have said about merging with machines (data/claims/, added 2026-10-16).
export type BearsOn = { kind: 'branch' | 'upgrade'; key: string; name: string; path: string; branch?: string; stage_label?: string };
export type Paraphrase = { repeated: string; seen: string; differs: string; primary_found: boolean };
export type Claim = {
  id: string;
  speaker: string;
  role: string | null;
  critic: boolean;
  when: string;
  when_label: string;
  when_note: string | null;
  released_on: string | null;
  occasion: string;
  status: 'sourced' | 'unsourced';
  ruling: string | null;
  source: string;
  source_url: string;
  source_locator: string | null;
  checked_how: string;
  words: string | null;
  words_locator: string | null;
  claimed: string;
  not_in_source: string | null;
  bears_on: BearsOn[];
  bears_on_note: string | null;
  coverage: string[];
  paraphrase: Paraphrase | null;
  why_here: string | null;
  notes: string | null;
  verify: string[];
  file: string;
};
export type Claims = {
  exported_on: string;
  claims: Claim[];
  not_entered: {
    checked: { who: string; role: string | null; checked: string; result: string }[];
    to_add: { lead: string; status: string }[];
  };
  counts: {
    claims: number; sourced: number; unsourced: number; critics: number; speakers: number;
    paraphrases: number; no_primary_found: number; to_verify: number;
    first_when: string | null; last_when: string | null;
  };
};

// The bandwidth series (data/bandwidth.toml, added 2026-10-16).
export type BandwidthPoint = {
  id: string;
  date: string;
  measure: string;
  value: number | null;
  unit: string | null;
  plot_value: number | null;
  no_figure: boolean;
  what: string;
  who: string;
  in_whom: string;
  repeated: string;
  peer_reviewed: boolean;
  source: string;
  source_note: string | null;
  upgrade: { id: string; name: string; path: string } | null;
  verify: string[];
  note: string | null;
};
export type Baseline = {
  id: string; measure: string; label: string; value: number; unit: string; plot_value: number;
  who: string; source: string; source_note: string | null;
};
export type Measure = {
  key: string; name: string; unit: string; conversion: string | null; meaning: string;
  points: BandwidthPoint[]; baselines: Baseline[];
  best: { id: string; date: string; value: number; unit: string; plot_value: number; peer_reviewed: boolean } | null;
};
export type Bandwidth = {
  exported_on: string;
  measures: Measure[];
  points: BandwidthPoint[];
  counts: { points: number; with_figures: number; baselines: number; to_verify: number; first_date: string | null; last_date: string | null };
};

export const tree = treeJson as Tree;
export const changelog = changelogJson as Changelog;
export const claims = claimsJson as Claims;
export const bandwidth = bandwidthJson as Bandwidth;

export const branchByKey = (key: string) => tree.branches.find((b) => b.key === key);
export const stageByKey = (key: StageKey) => tree.stages.find((s) => s.key === key)!;

export const statusLabel: Record<Upgrade['status'], string> = {
  tracked: 'Tracked',
  withdrawn: 'Withdrawn from use; the stage it reached stays on the record',
  superseded: 'Replaced by another entry',
};

/** "16 October 2026" from "2026-10-16". */
export function longDate(iso: string | null): string {
  if (!iso) return '';
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d)).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });
}

export function hostOf(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch {
    return url;
  }
}

/** A link that opens a new issue in the public repository with a title and body filled in. */
export function issueUrl(title: string, body: string): string {
  return `${REPO}/issues/new?title=${encodeURIComponent(title)}&body=${encodeURIComponent(body)}`;
}
